import unreal
paths=['/Game/SSPR_Validation/NS_SSPR_ProjTest.NS_SSPR_ProjTest:ProjParticles_0.GPUComputeScript','/Game/SSPR_Validation/NS_SSPR_ProjTest.NS_SSPR_ProjTest:ProjParticles_0.UpdateScript']
for p in paths:
    s=unreal.load_object(None,p)
    print('SCRIPT='+p+' found='+str(s is not None))
    if s is None: continue
    for prop in ['cached_script_vm','cached_default_data_interfaces']:
        try:
            v=s.get_editor_property(prop)
            print(prop+'='+repr(v))
            print(prop+'_DIR='+repr([x for x in dir(v) if any(k in x.lower() for k in ['interface','hlsl','compile','status','simulation','parameter'])]))
            if prop=='cached_script_vm':
                for q in ['data_interface_info','last_hlsl_translation_gpu','last_hlsl_translation','last_compile_status','simulation_stage_meta_data']:
                    try: print(q+'='+repr(v.get_editor_property(q)))
                    except Exception as e: print(q+'_ERR='+str(e))
        except Exception as e:
            print(prop+'_ERR='+str(e))
    del s
